// Generates TypeScript types for the API from its OpenAPI document.
// Run it (npm run api:generate) whenever the API's endpoints or DTOs change
import { writeFile } from 'node:fs/promises';
import openapiTS, { astToString } from 'openapi-typescript';

const apiUrl = process.env.VITE_API_URL || 'http://localhost:3000';
const source = process.env.OPENAPI_URL
  ? new URL(process.env.OPENAPI_URL)
  : new URL('/api/openapi.json', apiUrl);
const target = new URL('../src/shared/api/schema.d.ts', import.meta.url);

try {
  const ast = await openapiTS(source);
  const header =
    "// Generated by `npm run api:generate` from the API's OpenAPI document. Do not edit by hand\n\n";
  await writeFile(target, header + astToString(ast));
  console.log(`Generated src/shared/api/schema.d.ts from ${source}`);
} catch (err) {
  console.error(
    `Couldn't generate the API types from ${source}. Is the API running?`,
  );
  console.error(err);
  process.exit(1);
}
